"""FERPA & GDPR Educational Data Privacy Rules and Retention Models.

Enterprise Learning Management System - Institutional Academic Standards.
Module: gdpr_ferpa_compliance
"""

from dataclasses import dataclass, field
from typing import List, Dict, Optional, Any
from enum import Enum


class GDPR_FERPA_COMPLIANCE_BloomLevel(Enum):
    REMEMBER = "remember"
    UNDERSTAND = "understand"
    APPLY = "apply"
    ANALYZE = "analyze"
    EVALUATE = "evaluate"
    CREATE = "create"


class GDPR_FERPA_COMPLIANCE_CompetencyTier(Enum):
    NOVICE = "novice"
    INTERMEDIATE = "intermediate"
    ADVANCED = "advanced"
    EXPERT = "expert"


@dataclass
class GdprFerpaComplianceRecord:
    identifier: str
    title: str
    category: str
    weight: float
    difficulty: str
    prerequisites: List[str] = field(default_factory=list)
    tags: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "identifier": self.identifier,
            "title": self.title,
            "category": self.category,
            "weight": self.weight,
            "difficulty": self.difficulty,
            "prerequisites": self.prerequisites,
            "tags": self.tags,
            "metadata": self.metadata,
        }


