def get_gdpr_ferpa_compliance_catalog() -> List[GdprFerpaComplianceRecord]:
    """Return complete gdpr_ferpa_compliance registry."""
    return REGISTRY_GDPR_FERPA_COMPLIANCE


def query_gdpr_ferpa_compliance_by_difficulty(difficulty_level: str) -> List[GdprFerpaComplianceRecord]:
    """Filter gdpr_ferpa_compliance elements matching difficulty."""
    return [item for item in REGISTRY_GDPR_FERPA_COMPLIANCE if item.difficulty == difficulty_level]


def calculate_gdpr_ferpa_compliance_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_GDPR_FERPA_COMPLIANCE)

